#!/usr/bin/env node
// Tests for website/wallet-core.js and the scripts generated by website/wallet.js.
//
//   node website/test-wallet-core.mjs               # vectors + independent node:crypto derivation
//   node website/test-wallet-core.mjs --require-l1  # also cross-check against the built L1 (l1/dist)
//
// The L1 cross-check needs `cd l1 && npm ci && npm run build` first.
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { createECDH, createHash, randomBytes, webcrypto } from 'node:crypto';
import { chmodSync, existsSync, mkdirSync, mkdtempSync, readdirSync, readFileSync, rmSync, symlinkSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import vm from 'node:vm';

const here = dirname(fileURLToPath(import.meta.url));
const repo = resolve(here, '..');
const requireL1 = process.argv.includes('--require-l1');
let passed = 0;

async function test(name, fn) {
  try {
    await fn();
    passed += 1;
    console.log(`ok - ${name}`);
  } catch (error) {
    console.error(`not ok - ${name}`);
    throw error;
  }
}

function loadCore() {
  const context = { crypto: webcrypto, TextEncoder };
  context.globalThis = context;
  vm.createContext(context);
  vm.runInContext(readFileSync(join(here, 'wallet-core.js'), 'utf8'), context, { filename: 'wallet-core.js' });
  return context.ZyronWalletCore;
}

